-- OMAN-DEMO-KHASAB realistic DPR generation
-- 1) Lock all activities (DPR precondition)
-- 2) Wipe existing DPRs
-- 3) Insert fresh DPRs per working day with realistic crew + qty
-- 4) Update activity actuals (start/finish dates, percent_complete, status)
-- 5) Rollup resource_assignment actuals
BEGIN;
SET LOCAL session_replication_role = 'replica';

-- 1) Lock all OMAN activities
UPDATE activity.activities SET edit_status = 'LOCKED' WHERE project_id = 'd901671a-cd23-41c6-8886-d2c1b0ddd3c5';

-- 2) Wipe existing DPRs and dependent rows
DELETE FROM project.dpr_manpower  WHERE dpr_id IN (SELECT id FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5');
DELETE FROM project.dpr_equipment WHERE dpr_id IN (SELECT id FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5');
DELETE FROM project.dpr_material  WHERE dpr_id IN (SELECT id FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5');
DELETE FROM project.dpr_issues    WHERE dpr_id IN (SELECT id FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5');
DELETE FROM project.dpr_attachments WHERE dpr_id IN (SELECT id FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5');
DELETE FROM project.daily_activity_resource_outputs WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5';
DELETE FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5';

-- 2b) Reset resource_assignment actuals so the rollup at the end is authoritative
UPDATE resource.resource_assignments ra SET actual_units=0, actual_cost=0, remaining_units=COALESCE(planned_units,0), remaining_cost=COALESCE(planned_cost,0) WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5';

-- 3) Insert DPRs + child rows

-- 4) Update activity actuals based on generated DPRs
UPDATE activity.activities SET actual_start_date='2024-10-01', actual_finish_date='2024-10-31', percent_complete=99.96, status='COMPLETED' WHERE id='bc9fceea-66c5-4e13-8323-74a39afb1a39';
