SELECT 'dprs' AS what, count(*)::text FROM project.daily_progress_reports WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5'
UNION ALL SELECT 'dpr_manpower', count(*)::text FROM project.dpr_manpower m JOIN project.daily_progress_reports d ON d.id=m.dpr_id WHERE d.project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5'
UNION ALL SELECT 'dpr_equipment', count(*)::text FROM project.dpr_equipment e JOIN project.daily_progress_reports d ON d.id=e.dpr_id WHERE d.project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5'
UNION ALL SELECT 'activities locked', count(*)::text FROM activity.activities WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5' AND edit_status='LOCKED'
UNION ALL SELECT 'activities completed', count(*)::text FROM activity.activities WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5' AND status='COMPLETED'
ORDER BY what;

